window.confirmBooking = async () => { const pending = db.pendingBooking; if (!bookingSelectionIsValid(pending)) return text('book-error', 'This appointment time is no longer available. Select another time.'); Object.assign(pending, { forWhom: val('book-for'), guestName: val('book-name').trim(), guestMobile: val('book-mobile').trim(), note: val('book-note') }); if (!pending.guestMobile) return text('book-error', 'Enter a mobile number to book this appointment.'); if ((pending.forWhom === 'family' || pending.walkIn) && !pending.guestName) return text('book-error', 'Enter the guest name.'); sessionStorage.setItem(bookingDraftKey, JSON.stringify(pending)); if (!session) { loginRole = 'customer'; authMode = 'signin'; authModal = { trigger: 'booking', returnRoute: 'book' }; render(); return; } if (session.role === 'owner') { authModal = { trigger: 'role_mismatch' }; render(); return; } await submitBookingRequest(pending); };
async function persistBookingRequest(booking, customer, notification) {
  clearTimeout(saveTimer);
  for (let attempt = 0; attempt < 2; attempt += 1) {
    const response = await fetch('/api/state', { method: 'PUT', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ app: persistedAppState(), revision: stateRevision }) });
    const payload = await response.json().catch(() => ({}));
    if (response.ok) { stateRevision = payload.revision; return true; }
    if (response.status !== 409 || attempt === 1) throw new Error(payload.error || 'Unable to save your booking request.');
    const latestResponse = await fetch('/api/state', { cache: 'no-store' });
    if (!latestResponse.ok) throw new Error('Unable to refresh booking availability.');
    const latest = await latestResponse.json();
    db = { ...db, ...(latest.app || {}) };
    db.customers = [...(db.customers || []).filter((item) => item.id !== customer.id), customer];
    db.bookings = [...(db.bookings || []).filter((item) => item.id !== booking.id), booking];
    db.ownerNotifications = [notification, ...(db.ownerNotifications || []).filter((item) => item.bookingId !== booking.id)];
    stateRevision = latest.revision || 0;
  }
  return false;
}
async function submitBookingRequest(pending) {
  const service = db.services.find((item) => item.id === pending.serviceId);
  const possibleStaff = db.staff.filter((person) => person.salonId === pending.salonId && person.available && (pending.staffId === 'any' || person.id === pending.staffId));
  const staffId = possibleStaff.find((person) => !db.bookings.some((booking) => booking.staffId === person.id && booking.date === pending.date && booking.time === pending.time && ['Pending', 'Confirmed'].includes(booking.status)))?.id;
  if (!staffId) return text('book-error', 'That slot is no longer available. Please select another time.');
  let customer = ensureSessionCustomer();
  if (!pending.guestMobile?.trim()) return text('book-error', 'Enter a mobile number to book this appointment.');
  if (pending.forWhom === 'family' || pending.walkIn) {
    customer = { ...customer, id: `cus-${Date.now()}`, name: pending.guestName, mobile: pending.guestMobile, visits: 0, totalSpend: 0, favoriteSalons: [] };
    db.customers.push(customer);
  } else {
    customer.mobile = pending.guestMobile.trim();
  }
  const booking = { id: `book-${Date.now()}`, salonId: pending.salonId, customerId: customer.id, bookedByCustomerId: currentCustomer().id, serviceId: pending.serviceId, staffId, date: pending.date, time: pending.time, status: pending.walkIn || bookingRules(pending.salonId).confirmationMode === 'automatic' ? 'Confirmed' : 'Pending', amount: servicePrice(service, serviceOffers(service).find((offer) => offer.id === pending.offerId)).final, originalAmount: service.price, discountAmount: offerSaving(serviceOffers(service).find((offer) => offer.id === pending.offerId), service), duration: service.duration, note: pending.note || '', source: pending.walkIn ? 'walk_in' : 'online', paymentStatus: 'Pay at salon', campaignId: db.clickedCampaignId || '', offerId: pending.offerId || db.clickedOfferId || '' };
  if (booking.status === 'Confirmed' && !pending.walkIn) db.notifications.unshift({ customerId: customer.id, bookingId: booking.id, message: 'Your booking was confirmed automatically.', read: false });
  const notification = { salonId: booking.salonId, bookingId: booking.id, message: `New ${booking.source === 'walk_in' ? 'walk-in' : 'online'} booking from ${customer.name}`, read: false };
  db.bookings.push(booking);
  db.ownerNotifications.unshift(notification);
  try {
    await persistBookingRequest(booking, customer, notification);
  } catch (error) {
    db.bookings = db.bookings.filter((item) => item.id !== booking.id);
    db.ownerNotifications = db.ownerNotifications.filter((item) => item.bookingId !== booking.id);
    return text('book-error', error.message);
  }
  db.slotHolds = db.slotHolds.filter((hold) => hold.customerId !== currentCustomer().id);
  db.pendingBooking = null;
  sessionStorage.removeItem(bookingDraftKey);
  db.activeBookingId = booking.id;
  db.route = pending.walkIn ? 'owner-bookings' : 'booking-details';
  render();
}
