function favoriteServices(customerId) { return [...new Set(db.bookings.filter((b) => b.customerId === customerId).map((b) => db.services.find((s) => s.id === b.serviceId)?.name).filter(Boolean))].slice(0, 3); }
function segmentCustomers(id) { const salonCustomerIds = new Set(db.bookings.filter((b) => b.salonId === db.activeSalonId).map((b) => b.customerId)); return db.customers.filter((c) => { const visits = db.bookings.filter((b) => b.customerId === c.id && b.salonId === db.activeSalonId && b.status === 'Completed'); const last = lastVisit(c.id); const days = last ? Math.floor((new Date(today) - new Date(last)) / 86400000) : 999; const svc = favoriteServices(c.id); if (id === 'new') return !salonCustomerIds.has(c.id); if (id === 'regular') return visits.length >= 2; if (id === 'inactive-30') return visits.length > 0 && days >= 30; if (id === 'inactive-60') return visits.length > 0 && days >= 60; if (id === 'inactive-facial-60') return svc.includes('Facial') && days >= 60; if (id === 'birthday-month') return c.dob?.slice(5, 7) === '08'; if (id === 'high-value') return c.totalSpend >= 5000; if (id === 'female-nearby') return c.gender === 'Female' && ['Palakkad', 'Kinassery', 'Koduvayur'].includes(c.location); return false; }); }
function offers() { return `<h1>Targeted offers</h1>${card(`<h2>Create offer</h2><label>Offer title<input id="offer-title" placeholder="Offer title"></label><label>Description<input id="offer-description" placeholder="Describe the offer"></label><label>Discount type<select id="offer-type"><option>Percentage</option><option>Fixed amount</option><option>Buy one get one</option><option>Service bundle</option><option>First visit offer</option><option>Come-back offer</option><option>Birthday offer</option></select></label><label>Discount<input id="offer-discount" type="number" min="1"></label><label>Applicable service<input id="offer-service" placeholder="Service name"></label><label>Target segment<input id="offer-segment" value="${db.selectedSegmentId || ''}" placeholder="Audience segment"></label><label>End date<input id="offer-end" type="date" min="${today}"></label><label>Terms<input id="offer-terms" placeholder="Offer terms"></label><button onclick="previewOffer()">Preview</button> <button onclick="createOffer()">Submit for review</button><div id="offer-preview"></div>`)}<div class="grid three">${db.offers.filter((o) => o.salonId === db.activeSalonId).map(offerCard).join('')}</div>`; }
window.previewOffer = () => text('offer-preview', `${val('offer-title')} • ${val('offer-discount')}% • Target: ${val('offer-segment')} • Valid until ${val('offer-end')}`);
window.createOffer = () => { db.offers.unshift({ id: `offer-${Date.now()}`, salonId: db.activeSalonId, title: val('offer-title'), description: val('offer-description'), type: val('offer-type'), discount: Number(val('offer-discount')), service: val('offer-service'), segment: val('offer-segment'), start: today, end: val('offer-end'), minPurchase: 0, maxRedemptions: 100, terms: val('offer-terms'), approvalStatus: 'pending', status: 'pending', active: false, views: 0, clicks: 0, redemptions: 0 }); save(); render(); };
function marketing() { const ownerOffers = [...availablePlatformOffers(), ...db.offers.filter((o) => o.salonId === db.activeSalonId && offerIsEligible(o))]; const audiences = [['inactive-facial-60', 'Inactive facial', '60+ days'], ['regular', 'Regular customers', '2+ visits'], ['birthday-month', 'Birthdays', 'This month'], ['high-value', 'High value', '₹5,000+ spent']]; return `<div class="page-heading"><div><p class="eyebrow">Marketing</p><h1>Send a targeted campaign</h1><p>Choose an audience, offer and channel. Everything is managed in one place.</p></div></div><div class="grid stats audience-stats">${audiences.map(([id, label, rule]) => card(`<span>${label}</span><b>${segmentCustomers(id).length}</b><small>${rule}</small>`)).join('')}</div>${card(`<h2>Audience → Offer → Channel</h2><div class="form-grid"><label>Audience<select id="camp-segment">${audiences.map(([id, label]) => `<option value="${id}">${label} (${segmentCustomers(id).length})</option>`).join('')}</select></label><label>Offer<select id="camp-offer">${ownerOffers.length ? ownerOffers.map((o) => `<option value="${o.id}">${o.title}</option>`).join('') : '<option value="">No active offers available</option>'}</select></label><label>Channel<select id="camp-channel"><option>In-app notification</option><option>WhatsApp click-to-chat</option><option disabled>SMS (coming later)</option><option disabled>Email (coming later)</option></select></label></div><button onclick="sendCampaign()" ${ownerOffers.length ? '' : 'disabled'}>Send campaign</button>`)}<h2>Campaign history</h2><div class="grid three">${db.campaigns.filter((c) => c.salonId === db.activeSalonId).map(campaignCard).join('') || card('No campaigns sent yet.')}</div>`; }
window.sendCampaign = () => { const audience = segmentCustomers(val('camp-segment')); const campaign = { id: `camp-${Date.now()}`, salonId: db.activeSalonId, name: `${val('camp-segment')} campaign`, segmentId: val('camp-segment'), offerId: val('camp-offer'), channel: val('camp-channel'), status: 'Sent', targeted: audience.length, sent: audience.length, views: 0, clicks: 0, bookings: 0, redemptions: 0, revenue: 0 }; db.campaigns.unshift(campaign); db.notifications.push(...audience.map((c) => ({ customerId: c.id, campaignId: campaign.id, offerId: campaign.offerId, read: false }))); save(); render(); };
function campaignCard(c) { const offer = [...(db.platformOffers || []), ...db.offers].find((o) => o.id === c.offerId); return card(`<p class="pill">${c.status}</p><h3>${c.name}</h3><p>${offer?.title || 'Offer'} • ${c.channel}</p><p>Targeted ${c.targeted} • Sent ${c.sent} • Views ${c.views} • Clicks ${c.clicks}</p><p>Bookings ${c.bookings} • Redemptions ${c.redemptions} • Revenue ${fmt(c.revenue)}</p>`); }
function settings() {
  const s = salon();
  const staff = db.staff.filter((item) => item.salonId === s.id);
  const services = db.services.filter((item) => item.salonId === s.id);
  return `<div class="page-heading"><div><p class="eyebrow">Salon setup</p><h1>Manage your salon</h1><p>Update the details customers see when they book.</p></div><button onclick="openSalon('${s.id}')">View public page</button></div>
  ${card(`<h2>Salon details</h2><div class="form-grid"><label>Salon name<input id="salon-name" value="${s.name}"></label><label>Phone<input id="salon-phone" value="${s.phone}"></label><label>Address<input id="salon-address" value="${s.address}"></label><label>Town / location<input id="salon-location" value="${s.location}"></label><label>Opening hours<input id="salon-hours" value="${s.openingHours}"></label><label>WhatsApp number<input id="salon-whatsapp" value="${s.whatsapp}"></label></div><label>Description<textarea id="salon-description" rows="3">${s.description}</textarea></label><h3>Map location</h3><p class="help">Click or drag the pin to the salon entrance. This location is used for customer directions.</p><div id="salon-location-map" class="salon-location-map" data-latitude="${s.latitude ?? ''}" data-longitude="${s.longitude ?? ''}"></div><input id="salon-latitude" type="hidden" value="${s.latitude ?? ''}"><input id="salon-longitude" type="hidden" value="${s.longitude ?? ''}"><label>Salon photo<input id="salon-photo" type="file" accept="image/png,image/jpeg,image/webp" onchange="previewSalonPhoto(this)"></label><div id="photo-preview" class="photo-preview"><img src="${salonPhoto(s)}" alt="Salon photo preview"></div><p class="help">JPG, PNG or WebP. The demo stores the selected image in this browser.</p><button onclick="saveSalonDetails()">Save salon details</button>`) }
  ${card(`<h2>Booking availability</h2><div class="form-grid"><label>Minimum booking notice (hours)<input id="lead-hours" type="number" min="0" max="168" value="${bookingRules(s.id).leadHours}"></label><label>Booking window (days)<input id="window-days" type="number" min="1" max="365" value="${bookingRules(s.id).windowDays}"></label><label>Confirmation<select id="confirmation-mode"><option value="manual" ${bookingRules(s.id).confirmationMode === 'manual' ? 'selected' : ''}>Manual — owner confirms</option><option value="automatic" ${bookingRules(s.id).confirmationMode === 'automatic' ? 'selected' : ''}>Automatic — confirm immediately</option></select></label><label>Cancellation / reschedule cutoff (hours)<input id="cutoff-hours" type="number" min="0" value="${cancellationCutoff(s.id)}"></label><label>Add holiday<input id="holiday-date" type="date" min="${today}"></label><label>Block date<input id="block-date" type="date" min="${today}"></label><label>Block time<select id="block-time">${times.map((time) => `<option>${time}</option>`)}</select></label></div><div class="actions"><button onclick="saveBookingRules()">Save booking rules</button><button class="ghost" onclick="addHoliday()">Add holiday</button><button class="ghost" onclick="addBlockedTime()">Block time</button></div><p class="help">${db.holidays.filter((h) => h.salonId === s.id).length} holidays · ${db.blockedTimes.filter((b) => b.salonId === s.id).length} blocked slots. These are removed from customer availability automatically.</p>`) }
  <div class="section-heading"><div><h2>Services & pricing</h2><p>Set your own price and duration for every service.</p></div><button onclick="addService()">+ Add service</button></div>
  <div class="manage-list">${services.map(serviceEditor).join('')}</div>
  <div class="section-heading"><div><h2>Staff</h2><p>Keep team details and availability up to date.</p></div><button onclick="addStaff()">+ Add staff</button></div>
  <div class="grid two">${staff.map(staffEditor).join('')}</div>`;
}
function serviceEditor(service) { return card(`<div class="editor-row"><label>Service<input id="service-name-${service.id}" value="${service.name}"></label><label>Price (₹)<input id="service-price-${service.id}" type="number" min="0" value="${service.price}"></label><label>Minutes<input id="service-duration-${service.id}" type="number" min="5" step="5" value="${service.duration}"></label><label class="toggle"><input id="service-active-${service.id}" type="checkbox" ${service.active ? 'checked' : ''}> Active</label><button onclick="saveService('${service.id}')">Save</button><button class="danger" onclick="deleteService('${service.id}')">Delete</button></div>`); }
function staffEditor(person) { return card(`<h3>${person.name}</h3><div class="form-grid"><label>Name<input id="staff-name-${person.id}" value="${person.name}"></label><label>Phone<input id="staff-phone-${person.id}" value="${person.phone || ''}" placeholder="+91"></label><label>Specialization<input id="staff-specialization-${person.id}" value="${person.specialization}"></label><label>Working hours<input id="staff-hours-${person.id}" value="${person.hours}"></label></div><label class="toggle"><input id="staff-available-${person.id}" type="checkbox" ${person.available ? 'checked' : ''}> Available for bookings</label><div class="actions"><button onclick="saveStaff('${person.id}')">Save staff</button><button class="danger" onclick="deleteStaff('${person.id}')">Remove</button></div>`); }
window.saveSalonDetails = async () => { const latitude = Number(val('salon-latitude')); const longitude = Number(val('salon-longitude')); const business = { salonName: val('salon-name').trim(), phone: val('salon-phone').trim(), address: val('salon-address').trim(), town: val('salon-location').trim(), latitude, longitude, openingHours: val('salon-hours').trim(), whatsappNumber: val('salon-whatsapp').trim(), description: val('salon-description').trim(), image: salon().image || '' }; if (!business.salonName) return alert('Enter your official salon name.'); if (!val('salon-latitude') || !val('salon-longitude')) return alert('Set the salon location on the map.'); const response = await fetch('/api/auth/salon', { method: 'PUT', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(business) }); const payload = await response.json(); if (!response.ok) return alert(payload.error || 'Unable to save salon details.'); const mapped = salonFromApi(payload.salon); db.salons = db.salons.filter((item) => item.accountId !== session.accountId && item.ownerId !== session.accountId); db.salons.push(mapped); db.activeSalonId = mapped.id; render(); };
function initializeSalonLocationMap() { const element = document.getElementById('salon-location-map'); if (!element || element.dataset.ready || !window.L) return; element.dataset.ready = 'true'; const saved = [Number(element.dataset.latitude), Number(element.dataset.longitude)]; const hasSavedLocation = saved.every(Number.isFinite) && element.dataset.latitude !== '' && element.dataset.longitude !== ''; const center = hasSavedLocation ? saved : [10.7867, 76.6548]; const map = L.map(element).setView(center, hasSavedLocation ? 16 : 12); L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', { maxZoom: 19, attribution: '&copy; OpenStreetMap contributors' }).addTo(map); const marker = L.marker(center, { draggable: true }).addTo(map); const select = ({ lat, lng }) => { marker.setLatLng([lat, lng]); document.getElementById('salon-latitude').value = lat.toFixed(6); document.getElementById('salon-longitude').value = lng.toFixed(6); }; map.on('click', (event) => select(event.latlng)); marker.on('dragend', () => select(marker.getLatLng())); }
window.saveBookingRules = async () => { const current = salon(); const rules = { bookingLeadTimeHours: Math.min(168, Math.max(0, Number(val('lead-hours')))), bookingWindowDays: Math.min(365, Math.max(1, Math.round(Number(val('window-days'))))), confirmationMode: val('confirmation-mode') }; const response = await fetch('/api/auth/salon', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(rules) }); const payload = await response.json(); if (!response.ok) return alert(payload.error || 'Unable to save booking rules.'); Object.assign(current, rules, { cancellationCutoffHours: Math.max(0, Number(val('cutoff-hours'))) }); save(); render(); };
window.addHoliday = () => { if (!val('holiday-date')) return; db.holidays.push({ salonId: db.activeSalonId, date: val('holiday-date') }); save(); render(); };
window.addBlockedTime = () => { if (!val('block-date')) return; db.blockedTimes.push({ salonId: db.activeSalonId, date: val('block-date'), time: val('block-time') }); save(); render(); };
window.previewSalonPhoto = (input) => { const file = input.files?.[0]; if (!file || file.size > 2 * 1024 * 1024) return alert('Choose a JPG, PNG or WebP image smaller than 2 MB.'); const reader = new FileReader(); reader.onload = () => { salon().image = reader.result; save(); document.querySelector('#photo-preview img').src = reader.result; }; reader.readAsDataURL(file); };
window.saveService = (id) => { const service = db.services.find((item) => item.id === id); Object.assign(service, { name: val(`service-name-${id}`).trim(), price: Number(val(`service-price-${id}`)), duration: Number(val(`service-duration-${id}`)), active: document.getElementById(`service-active-${id}`).checked }); save(); render(); };
window.addService = () => { db.services.unshift({ id: `service-${Date.now()}`, salonId: db.activeSalonId, name: 'New service', category: 'Beauty', price: 0, duration: 30, active: true }); save(); render(); };
window.deleteService = (id) => { if (!confirm('Delete this service?')) return; db.services = db.services.filter((item) => item.id !== id); save(); render(); };
window.saveStaff = (id) => { const person = db.staff.find((item) => item.id === id); Object.assign(person, { name: val(`staff-name-${id}`).trim(), phone: val(`staff-phone-${id}`).trim(), specialization: val(`staff-specialization-${id}`).trim(), hours: val(`staff-hours-${id}`).trim(), available: document.getElementById(`staff-available-${id}`).checked }); save(); render(); };
window.addStaff = () => { db.staff.unshift({ id: `staff-${Date.now()}`, salonId: db.activeSalonId, name: 'New staff member', phone: '', specialization: 'Beautician', hours: '9 AM - 6 PM', available: true }); save(); render(); };
window.deleteStaff = (id) => { if (!confirm('Remove this staff member?')) return; db.staff = db.staff.filter((item) => item.id !== id); save(); render(); };
function adminDashboard() { return `<h1>Admin dashboard</h1><div class="grid stats">${[['Total salons', db.salons.length], ['Active salons', db.salons.filter((s) => !s.suspended).length], ['Total customers', db.customers.length], ['Total bookings', db.bookings.length], ['Total offers', db.offers.length], ['Campaigns sent', db.campaigns.filter((c) => c.status === 'Sent').length], ['Monthly active salons', 4]].map(([a, b]) => card(`<span>${a}</span><b>${b}</b>`)).join('')}</div>`; }
function adminSalons() { return `<h1>Manage salons</h1><div class="grid three">${db.salons.map((s) => card(`<h3>${s.name}</h3><p>${s.location} • ${s.approved ? 'Approved' : 'Pending'} • ${s.suspended ? 'Suspended' : 'Active'}</p><button onclick="toggleSalon('${s.id}','approved')">${s.approved ? 'Reject' : 'Approve'}</button> <button class="ghost" onclick="toggleSalon('${s.id}','suspended')">${s.suspended ? 'Unsuspend' : 'Suspend'}</button>`)).join('')}</div>`; }
window.toggleSalon = (id, field) => { const s = db.salons.find((item) => item.id === id); s[field] = !s[field]; save(); render(); };
const adminCustomers = () => `<h1>Customers & owners</h1><div class="grid three">${db.customers.map((c) => card(`<h3>${c.name}</h3><p>${c.mobile} • ${c.location}</p><button class="${c.disabled ? '' : 'danger'}" onclick="toggleCustomer('${c.id}')">${c.disabled ? 'Enable account' : 'Disable account'}</button>`)).join('')}</div>`;
window.toggleCustomer = (id) => { const customer = db.customers.find((c) => c.id === id); customer.disabled = !customer.disabled; save(); render(); };
const adminBookings = () => `<h1>All bookings</h1>${db.bookings.slice(0, 25).map(customerBookingCard).join('')}`;
const adminCampaigns = () => `<h1>Offers & app banners</h1>${card(`<h2>Platform offer rules</h2><p>Pay-at-salon only · No misleading discounts · Salon approval required</p><label>Customer app banner<input id="admin-banner" value="${db.appBanner || 'Book trusted salons across Palakkad'}"></label><button onclick="db.appBanner=val('admin-banner');save();render()">Save banner</button>`)}<h2>Campaign report</h2><div class="grid three">${db.campaigns.map(campaignCard).join('')}</div>`;
function val(id) { return document.getElementById(id)?.value || ''; }
function text(id, value) { document.getElementById(id).textContent = value; }
function recommendedOffers() { return db.notifications.filter((n) => n.customerId === currentCustomer().id).map((n) => db.offers.find((o) => o.id === n.offerId)).filter(offerIsEligible).concat(db.offers.filter(offerIsEligible).slice(0, 5)); }
function render() { const publicRoutes = ['home', 'explore', 'salon-profile', 'book']; if (!session && !publicRoutes.includes(db.route)) db.route = 'home'; const routes = { home: customerHome, register, explore, 'salon-profile': salonProfile, book: booking, 'booking-details': bookingDetails, 'my-bookings': myBookings, 'my-offers': myOffers, profile, 'owner-dashboard': ownerDashboard, 'owner-bookings': ownerBookings, crm, offers, marketing, settings, 'admin-dashboard': adminDashboard, 'admin-salons': adminSalons, 'admin-customers': adminCustomers, 'admin-bookings': adminBookings, 'admin-campaigns': adminCampaigns }; const mobileRoutes = !session ? [['home', '⌂', 'Home'], ['explore', '⌕', 'Search']] : db.role === 'customer' ? [['home', '⌂', 'Home'], ['explore', '⌕', 'Search'], ['my-bookings', '□', 'Bookings'], ['profile', '♙', 'Profile']] : db.role === 'owner' ? [['owner-dashboard', '⌂', 'Home'], ['owner-bookings', '□', 'Bookings'], ['crm', '♙', 'Customers'], ['marketing', '◇', 'Marketing'], ['settings', '⚙', 'Setup']] : [['admin-dashboard', '⌂', 'Home'], ['admin-salons', '◇', 'Salons'], ['admin-bookings', '□', 'Bookings'], ['admin-campaigns', '↗', 'Campaigns']]; root.innerHTML = nav() + `<main>${routes[db.route]?.() || customerHome()}</main><footer>${mobileRoutes.map(([key, icon, label]) => `<button class="${db.route === key ? 'active' : ''}" onclick="navigate('${key}')"><span>${icon}</span><small>${label}</small></button>`).join('')}</footer>${authDialog()}`; if (db.route === 'settings') setTimeout(initializeSalonLocationMap, 0); if (authModal && authModal.trigger !== 'role_mismatch') setTimeout(() => initializeHomeGoogleLogin(), 0); }
render();
fetch('/api/auth/session', { cache: 'no-store' }).then((response) => response.ok ? response.json() : null).then(async (active) => { db.route = routeForPath() || 'home'; authModal = null; if (active) { const activeRole = active.activeRole === 'salon_owner' ? 'owner' : active.activeRole === 'customer' ? 'customer' : active.roles.length === 1 && active.roles.includes('salon_owner') ? 'owner' : 'customer'; session = { ...active, accountId: active.sub, role: activeRole }; db.role = session.role; await hydrateDatabase(); if (session.role === 'owner') { const ownedSalon = ensureOwnerSalon(session); db.activeSalonId = ownedSalon.id; save(); db.route = ownedSalon.name ? (routeForPath() || 'owner-dashboard') : 'settings'; history.replaceState({}, '', ownedSalon.name ? (routeForPath() === 'settings' ? '/partner/setup' : '/partner/dashboard') : '/partner/setup'); render(); } else { ensureSessionCustomer(); render(); } } else { await hydratePublicSalons(); const requestedRoute = routeForPath(); if (requestedRoute && !['home', 'explore'].includes(requestedRoute)) { const ownerRoute = requestedRoute === 'owner-dashboard' || requestedRoute === 'settings'; authModal = { trigger: 'universal', returnRoute: requestedRoute }; loginRole = ownerRoute ? 'salon_owner' : 'customer'; } render(); } }).catch(() => {});
window.addEventListener('popstate', () => { const route = routeForPath(); if (route && session) { db.route = route; render(); } });
